35: /// A fixed-capacity ring. The oldest insertion is overwritten when it is full,
36: /// so entries live in insertion order in a Vec.
37: pub struct RingStore {
38:     slots: Vec<(String, String)>,
39:     cap: usize,
40:     next: usize,
41: }
42: 
43: impl RingStore {
44:     pub fn with_capacity(cap: usize) -> Self {
